export type SeatStatus = 'Free' | 'Occupied';

export interface Seat {
  seatId: string;
  row: string;
  column: number;
  status: SeatStatus;
}

export interface PriceCategory {
  id: string;
  name: string;
  price: number;
}

export interface SeatMap {
  eventId: string;
  rows: string[];
  columns: number;
  aisleColumns: number[];
  seats: Seat[];
  priceCategories: PriceCategory[];
}

const euroFormatter = new Intl.NumberFormat('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

export function formatEuroAmount(amount: number): string {
  return `${euroFormatter.format(amount)} €`;
}

.price-category-panel {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-2);
  padding: var(--spacing-2) var(--spacing-1);
}

.price-category-panel__pill {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-1);
  padding: var(--spacing-1) var(--spacing-3);
  border-radius: var(--radius-full);
  border: 1px solid var(--color-border-hairline);
  background: var(--color-surface-raised);
  color: var(--color-ink-primary);
  font-size: var(--text-label-size);
  font-weight: var(--text-label-weight);
  line-height: var(--text-label-line-height);
  cursor: pointer;
}

.price-category-panel__pill--active {
  border-color: var(--color-accent);
  border-width: 2px;
}

.price-category-panel__pill:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}
---
.sitzplan-page__error {
  color: var(--color-danger);
}

.sitzplan-page__layout {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-4);
}

.sitzplan-page__summary {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 10;
}

@media (min-width: 768px) {
  .sitzplan-page__layout {
    flex-direction: row;
    align-items: flex-start;
  }

  .sitzplan-page__viewport {
    flex: 1;
    min-width: 0;
  }

  .sitzplan-page__summary {
    position: sticky;
    top: var(--spacing-4);
    bottom: auto;
    left: auto;
    right: auto;
    flex: 0 0 320px;
  }
}

.sitzplan-page__viewport {
  overflow: hidden;
  touch-action: none;
  background-color: var(--color-surface-base);
  border: 1px solid var(--color-border-hairline);
  border-radius: var(--radius-md);
  padding: var(--spacing-4);
}

.sitzplan-page__grid {
  display: grid;
  gap: var(--spacing-1);
  transform-origin: top left;
  width: fit-content;
}

.sitzplan-page__aisle {
  min-width: 32px;
  min-height: 32px;
  background-color: var(--color-surface-base);
}

.sitzplan-page__corner {
  min-width: 32px;
  min-height: 32px;
}

.sitzplan-page__column-label,
.sitzplan-page__row-label {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--text-meta-size);
  font-weight: var(--text-meta-weight);
  line-height: var(--text-meta-line-height);
  letter-spacing: var(--text-meta-letter-spacing);
  color: var(--color-ink-secondary);
}

.sitzplan-page__column-label {
  min-width: 32px;
}

.sitzplan-page__row-label {
  min-height: 32px;
  padding-inline-end: var(--spacing-1);
}

.sitzplan-page__price-panel {
  grid-column: 1 / -1;
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border-hairline);
  border-radius: var(--radius-md);
  margin-block: var(--spacing-1);
}

.sitzplan-page__grid--placeholder {
  gap: var(--spacing-1);
}

.sitzplan-page__placeholder-cell {
  min-width: 32px;
  min-height: 32px;
  background-color: var(--color-surface-sunken);
  border-radius: var(--radius-sm);
}

